mapper.sql:
WHERE quotations.status > 0

    AND (
    quotations.quotation_code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND quotations.quotation_date >= #{filter.dateFrom}


    AND quotations.quotation_date <= #{filter.dateTo}


    AND quotations.type = #{filter.type}


    AND quotations.customer_id = #{filter.organizationId}


    AND quotations.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})


    AND quotations.id IN (SELECT quotation_id FROM quotation_details WHERE product_id = #{filter.productId})


    AND quotations.is_close = #{filter.isClose}


    AND quotations.is_approve = #{filter.isApprove}


    AND quotations.created_by = #{filter.createdBy}


    AND quotations.is_none_vat = #{filter.filterBy}


    AND quotations.id IN (SELECT quotation_id FROM order_quotations WHERE order_id IS NOT NULL)

mapper.select:
SELECT quotations.id AS id, quotations.quotation_date AS quotationDate, quotations.quotation_code AS quotationCode, CONCAT(customers.name_kh, ' (', customers.name, ')') AS organizationName, (SELECT GROUP_CONCAT((SELECT order_code FROM orders WHERE id = order_quotations.order_id AND status > 0)) FROM order_quotations WHERE order_quotations.quotation_id = quotations.id) AS orderCode, quotations.total_amount - IFNULL(quotations.discount, 0) AS totalAmount, IFNULL(quotations.total_vat, 0) AS totalVat, (SELECT CONCAT(DATEDIFF(quotations.modified, quotations.created), ' ', 'day(s)') FROM quotations quot WHERE quot.is_close = 1 AND quot.id = quotations.id) AS aging, quotations.is_close AS isClose, quotations.is_approve AS isApprove, quotations.type AS type, CONCAT(users.first_name, ' ', users.last_name) AS createdBy, currency_centers.symbol AS currencySymbol
ORDER BY quotations.quotation_date DESC, quotations.quotation_code DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT quotations.id AS id, quotations.quotation_date AS quotationDate, quotations.quotation_code AS quotationCode, CONCAT(customers.name_kh, ' (', customers.name, ')') AS organizationName
GROUP BY quotations.quotation_date DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}
